/** A free slot visible at reader admission does not grant membership to its later replacement. */
@Timeout(30)
class LmdbPersistedFreeIdVisibilityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@ParameterizedTest
	@MethodSource("shapesAndInitialization")
	void oldPairedLookupDoesNotBorrowReadyReplacementOfPersistedFreeId(Shape shape, boolean completed,
			@TempDir Path directory) throws Exception {
		File valuesDirectory = directory.resolve("values").toFile();
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		Value original = VF.createBNode("persisted-free-retired");
		Value replacement = shape.value(true);
		long retiredId = retireReadyValue(valuesDirectory, config, original, replacement);
		CloseableValueStore valuesResource = new CloseableValueStore(new ValueStore(valuesDirectory, config));
		ValueStore values = valuesResource.values();
		try (valuesResource;
				TripleStore triples = new TripleStore(directory.resolve("triples").toFile(), config, values);
				TxnManager.ReaderReservation oldTripleReservation = triples.getTxnManager().reserveReadTxn(false);
				Txn oldTripleTxn = oldTripleReservation.startPinned(triples::getDataRevision);
				ValueStore.ReadSnapshotReservation oldReservation = values.reserveReadSnapshot();
				ValueStore.ReadSnapshot oldSnapshot = oldReservation.start(oldTripleTxn)) {
			oldSnapshot.retainStableIds(oldTripleTxn);
			assertTrue(values.getLmdbStats().get("free_ids").entries() > 0,
					"Normal reopen must leave the retired slot in the persisted free-ID database");
			assertNull(values.getValue(oldSnapshot, retiredId),
					"The held dictionary reader must see a genuinely free slot before replacement");
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(oldSnapshot, replacement));
			values.startTransaction(true);
			long replacementId = values.storeValue(replacement);
			values.commit();
			assertEquals(ValueIds.getValue(retiredId), ValueIds.getValue(replacementId),
					"The ready-only writer must really reuse the persisted logical ID, including type retagging");
			if (shape == Shape.BNODE_VALUE) {
				assertEquals(retiredId, replacementId, "Blank-node replacement must reuse the exact compound ID");
			}
			assertNull(values.getValue(oldSnapshot, replacementId));
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(oldSnapshot, replacement),
					"The lexical control must remain absent from the exact older native reader");
			LmdbValue escaped;
			ValueStoreRevision issuingRevision;
			try (TxnManager.ReaderReservation newTripleReservation = triples.getTxnManager().reserveReadTxn(false);
					Txn newTripleTxn = newTripleReservation.startPinned(triples::getDataRevision);
					ValueStore.ReadSnapshotReservation newReservation = values.reserveReadSnapshot();
					ValueStore.ReadSnapshot newSnapshot = newReservation.start(newTripleTxn)) {
				newSnapshot.retainStableIds(newTripleTxn);
				assertEquals(replacementId, values.getId(newSnapshot, replacement),
						"The issuing reader must prove the replacement's actual native membership");
				escaped = values.getLazyValue(newSnapshot, replacementId);
				issuingRevision = newSnapshot.revision();
				assertInstanceOf(ValueStoreRevision.Lazy.class, escaped.getValueStoreRevision());
			}
			if (completed) {
				escaped.init();
				assertEquals(replacement, escaped,
						"The free old slot must yield to a reader that contains the committed replacement");
			}
			boolean sharedEpoch = oldSnapshot.revision() == issuingRevision;
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(oldSnapshot, escaped),
					"Persisted free-ID visibility must not become replacement membership; sharedEpoch=" + sharedEpoch
							+ ", completed=" + completed + ", shape=" + shape);
		}
	}

	private static long retireReadyValue(File directory, LmdbStoreConfig config, Value original, Value replacement)
			throws IOException {
		CloseableValueStore valuesResource = new CloseableValueStore(new ValueStore(directory, config));
		ValueStore values = valuesResource.values();
		try (valuesResource) {
			values.startTransaction(true);
			storeReplacementChildren(values, replacement);
			long id = values.storeValue(original);
			values.commit();
			assertNotEquals(LmdbValue.UNKNOWN_ID, id);
			assertFalse(ValueIds.isInlined(id));
			values.startTransaction(true);
			values.gcIds(Set.of(id), new HashSet<>());
			values.commit();
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(original));
			return id;
		}
	}

	private record CloseableValueStore(ValueStore values) implements AutoCloseable {
		@Override
		public void close() throws IOException {
			values.close();
		}
	}

	private static void storeReplacementChildren(ValueStore values, Value replacement) throws IOException {
		if (replacement instanceof TripleTerm term) {
			values.storeValue(term.getSubject());
			values.storeValue(term.getPredicate());
			values.storeValue(term.getObject());
		} else if (replacement instanceof Literal literal) {
			values.storeValue(literal.getDatatype());
		} else if (replacement instanceof IRI iri) {
			values.storeValue(VF.createIRI(iri.getNamespace(), "namespace-anchor"));
		}
	}

	private static Stream<Arguments> shapesAndInitialization() {
		return Stream.of(Shape.values())
				.flatMap(shape -> Stream.of(Arguments.of(shape, false), Arguments.of(shape, true)));
	}

	enum Shape {
		IRI_VALUE,
		BNODE_VALUE,
		TYPED_LITERAL,
		DIRECTIONAL_LITERAL,
		TRIPLE_TERM,
		NESTED_TRIPLE_TERM;

		Value value(boolean replacement) {
			String suffix = replacement ? "replacement" : "retired";
			IRI subject = VF.createIRI("urn:persisted-free:subject");
			IRI predicate = VF.createIRI("urn:persisted-free:predicate");
			IRI datatype = VF.createIRI("urn:persisted-free:datatype");
			Literal literal = VF.createLiteral(suffix + " native literal payload", datatype);
			return switch (this) {
			case IRI_VALUE -> VF.createIRI("urn:persisted-free:" + suffix);
			case BNODE_VALUE -> VF.createBNode("persisted-free-" + suffix);
			case TYPED_LITERAL -> literal;
			case DIRECTIONAL_LITERAL -> VF.createLiteral(suffix + " directional native payload", "en",
					Literal.BaseDirection.LTR);
			case TRIPLE_TERM -> VF.createTripleTerm(subject, predicate, VF.createBNode("persisted-free-" + suffix));
			case NESTED_TRIPLE_TERM -> VF.createTripleTerm(subject, predicate,
					VF.createTripleTerm(subject, predicate, VF.createBNode("persisted-free-" + suffix)));
			};
		}
	}
}
